class Solution {
  public int[] longestCommonPrefix(String[] words, int k) {
    int n = words.length;
    int[] ans = new int[n];
    if (n - 1 < k) return ans;
    int total = 1;
    for (String w : words) total += w.length();
    int[][] child = new int[total][];
    int[] count = new int[total], depth = new int[total];
    int nodes = 1;
    for (String w : words) {
      int cur = 0;
      for (int i = 0; i < w.length(); i++) {
        int c = w.charAt(i) - 'a';
        if (child[cur] == null) child[cur] = new int[26];
        if (child[cur][c] == 0) {
          child[cur][c] = nodes;
          depth[nodes] = depth[cur] + 1;
          nodes++;
        }
        cur = child[cur][c];
        count[cur]++;
      }
    }
    int maxLen = 0;
    for (String w : words) maxLen = Math.max(maxLen, w.length());
    int[] fragile = new int[maxLen + 2];
    int robust = 0, topFragile = 0;
    for (int v = 1; v < nodes; v++) {
      if (count[v] > k) robust = Math.max(robust, depth[v]);
      else if (count[v] == k) {
        fragile[depth[v]]++;
        topFragile = Math.max(topFragile, depth[v]);
      }
    }
    int[] path = new int[maxLen + 1];
    for (int idx = 0; idx < n; idx++) {
      String w = words[idx];
      int cur = 0, len = w.length();
      for (int i = 0; i < len; i++) {
        cur = child[cur][w.charAt(i) - 'a'];
        path[i + 1] = cur;
      }
      int best = robust;
      if (topFragile > len) best = Math.max(best, topFragile);
      else {
        for (int d = len; d >= 1 && d > best; d--) {
          int onPath = count[path[d]] == k ? 1 : 0;
          if (fragile[d] - onPath > 0) {
            best = d;
            break;
          }
        }
      }
      ans[idx] = best;
    }
    return ans;
  }
}
